INSERT INTO exercises
  (id,skill,level,objective,instructions,content,answer_key,explanation,
   estimated_time,tags,prerequisites,srs,success_criteria,language_code)
VALUES
('DE-A1-01','vocabulary','A1','Поздороваться в разное время суток','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Welche Begrüßung passt zum Morgen?","options":[{"id":"a","text":"Guten Morgen!"},{"id":"b","text":"Gute Nacht!"},{"id":"c","text":"Guten Abend!"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Guten Morgen говорит утром.","en":"Guten Morgen is used in the morning."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"vocabulary"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-02','grammar','A1','Использовать глагол sein в настоящем времени','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich ___ Anna. Und wer bist du?","options":[{"id":"a","text":"bin"},{"id":"b","text":"bist"},{"id":"c","text":"ist"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"С местоимением ich используется форма bin.","en":"Use bin with the subject ich."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-03','grammar','A1','Выбирать неопределённый артикль','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Das ist ___ Buch.","options":[{"id":"a","text":"ein"},{"id":"b","text":"eine"},{"id":"c","text":"einen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Buch — существительное среднего рода: das Buch. В именительном падеже используется ein.","en":"Buch is neuter: das Buch. The nominative indefinite article is ein."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-04','vocabulary','A1','Спрашивать цену и понимать простой ответ','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Wie viel kostet das? — Es kostet fünf ___.","options":[{"id":"a","text":"Euro"},{"id":"b","text":"Jahre"},{"id":"c","text":"Uhren"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Euro — валюта; Jahre означает годы, Uhren — часы.","en":"Euro is the currency; Jahre means years and Uhren means clocks."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"vocabulary"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-05','communication','A1','Понимать вопрос о месте жительства','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Wo wohnst du? — Ich wohne ___ Berlin.","options":[{"id":"a","text":"in"},{"id":"b","text":"aus"},{"id":"c","text":"mit"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Для города обычно используется in: in Berlin wohnen.","en":"Use in with a city: in Berlin wohnen."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-06','grammar','A1','Спрягать haben с местоимением wir','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Wir ___ einen Hund.","options":[{"id":"a","text":"haben"},{"id":"b","text":"hat"},{"id":"c","text":"hast"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"С wir используется форма haben.","en":"Use haben with the subject wir."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-07','grammar','A1','Образовывать множественное число существительных','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Das sind zwei ___.","options":[{"id":"a","text":"Bücher"},{"id":"b","text":"Buch"},{"id":"c","text":"Buches"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Множественное число от das Buch — die Bücher.","en":"The plural of das Buch is die Bücher."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-08','grammar','A1','Использовать Akkusativ с неопределённым артиклем','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich kaufe ___ Apfel.","options":[{"id":"a","text":"einen"},{"id":"b","text":"ein"},{"id":"c","text":"eine"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Apfel — мужского рода; после kaufe нужен Akkusativ: einen Apfel.","en":"Apfel is masculine; the accusative form is einen Apfel."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-09','grammar','A1','Использовать отделяемую приставку в предложении','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich stehe jeden Tag um sieben Uhr ___.","options":[{"id":"a","text":"auf"},{"id":"b","text":"an"},{"id":"c","text":"aus"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"У глагола aufstehen отделяемая приставка auf переходит в конец предложения.","en":"The separable prefix auf in aufstehen moves to the end of the clause."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-10','vocabulary','A1','Назвать дни недели','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Der Tag nach Montag ist ___.","options":[{"id":"a","text":"Dienstag"},{"id":"b","text":"Sonntag"},{"id":"c","text":"Freitag"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"После Montag идёт Dienstag.","en":"Dienstag follows Montag."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"vocabulary"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-11','grammar','A1','Выбирать притяжательное местоимение mein/meine','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Das ist ___ Mutter.","options":[{"id":"a","text":"meine"},{"id":"b","text":"mein"},{"id":"c","text":"meinen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Mutter — женского рода, поэтому используется meine.","en":"Mutter is feminine, so use meine."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-12','grammar','A1','Отрицать существительное с помощью kein','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich habe ___ Auto.","options":[{"id":"a","text":"kein"},{"id":"b","text":"nicht"},{"id":"c","text":"keine"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Auto — среднего рода; перед существительным используется kein.","en":"Auto is neuter; use kein before the noun."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-13','communication','A1','Спросить дорогу и назвать направление','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich gehe ___ Schule.","options":[{"id":"a","text":"zur"},{"id":"b","text":"aus"},{"id":"c","text":"mit"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Zur — сокращение zu der; Schule здесь женского рода.","en":"Zur is short for zu der; Schule is feminine."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A1-14','grammar','A1','Использовать Perfekt с haben','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Gestern habe ich Fußball ___.","options":[{"id":"a","text":"gespielt"},{"id":"b","text":"spiele"},{"id":"c","text":"spielen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Perfekt образуется с haben и Partizip II: habe gespielt.","en":"Perfekt uses haben plus the past participle: habe gespielt."}'::jsonb,3,ARRAY['german','a1'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-01','grammar','A2','Выбирать вспомогательный глагол в Perfekt движения','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Wir ___ gestern nach Berlin gefahren.","options":[{"id":"a","text":"sind"},{"id":"b","text":"haben"},{"id":"c","text":"werden"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Для fahren в значении перемещения обычно используется sein: sind gefahren.","en":"Movement with fahren normally uses sein: sind gefahren."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-02','grammar','A2','Использовать Dativ после helfen','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich helfe ___ Bruder.","options":[{"id":"a","text":"meinem"},{"id":"b","text":"meinen"},{"id":"c","text":"meiner"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Глагол helfen требует Dativ; у Bruder мужской род: meinem Bruder.","en":"Helfen takes the dative; Bruder is masculine: meinem Bruder."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-03','grammar','A2','Ставить глагол в конец придаточного с weil','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich bleibe zu Hause, weil ich krank ___.","options":[{"id":"a","text":"bin"},{"id":"b","text":"bist"},{"id":"c","text":"ist"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"В придаточном предложении с weil спрягаемый глагол стоит в конце.","en":"In a weil clause, the conjugated verb goes to the end."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-04','grammar','A2','Образовывать сравнительную степень прилагательного','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Der Zug ist ___ als der Bus.","options":[{"id":"a","text":"schneller"},{"id":"b","text":"am schnellsten"},{"id":"c","text":"schnell"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Сравнительная степень von schnell — schneller; после неё часто используется als.","en":"The comparative of schnell is schneller and is commonly followed by als."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-05','communication','A2','Давать вежливый совет с sollten','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Du ___ früher schlafen gehen.","options":[{"id":"a","text":"solltest"},{"id":"b","text":"soll"},{"id":"c","text":"sollte"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Для совета собеседнику используется solltest.","en":"Use solltest to give advice to du."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-06','grammar','A2','Согласовывать прилагательное с существительным','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Sie trägt eine ___ Jacke.","options":[{"id":"a","text":"blaue"},{"id":"b","text":"blauer"},{"id":"c","text":"blaues"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"После eine перед существительным женского рода прилагательное получает окончание -e.","en":"After eine before a feminine noun, the adjective takes -e."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-07','vocabulary','A2','Спрашивать, как давно длится действие','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"___ lernst du schon Deutsch? — Seit einem Jahr.","options":[{"id":"a","text":"Seit wann"},{"id":"b","text":"Wohin"},{"id":"c","text":"Wie viel"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Seit wann спрашивает о начале периода, продолжающегося до настоящего момента.","en":"Seit wann asks when an ongoing period began."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"vocabulary"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-08','grammar','A2','Использовать Präteritum глагола sein','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Als Kind ___ ich oft bei meinen Großeltern.","options":[{"id":"a","text":"war"},{"id":"b","text":"bin"},{"id":"c","text":"gewesen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Präteritum глагола sein для ich — war.","en":"The Präteritum form of sein with ich is war."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-09','grammar','A2','Выбирать Dativ для положения с предлогом auf','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Das Buch liegt auf ___ Tisch.","options":[{"id":"a","text":"dem"},{"id":"b","text":"den"},{"id":"c","text":"der"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Положение без изменения направления требует Dativ; der Tisch становится dem Tisch.","en":"A static location takes the dative; der Tisch becomes dem Tisch."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-10','grammar','A2','Использовать zu + Infinitiv','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich habe vergessen, die Tür ___.","options":[{"id":"a","text":"abzuschließen"},{"id":"b","text":"abschließe"},{"id":"c","text":"abgeschlossen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"После vergessen можно использовать zu + Infinitiv; у отделяемого глагола zu ставится между приставкой и основой.","en":"After vergessen, use zu + infinitive; with a separable verb, zu goes inside."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-11','grammar','A2','Использовать предлог für с sich interessieren','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Ich interessiere mich ___ Musik.","options":[{"id":"a","text":"für"},{"id":"b","text":"auf"},{"id":"c","text":"an"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Устойчивое управление: sich für etwas interessieren.","en":"The fixed construction is sich für etwas interessieren."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-12','communication','A2','Вежливо просить о помощи в Konjunktiv II','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"___ Sie mir bitte helfen?","options":[{"id":"a","text":"Könnten"},{"id":"b","text":"Können"},{"id":"c","text":"Konnten"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Könnten Sie — вежливая просьба в Konjunktiv II.","en":"Könnten Sie is a polite request using Konjunktiv II."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-13','grammar','A2','Строить условное предложение с wenn','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Wenn ich mehr Zeit ___, würde ich öfter lesen.","options":[{"id":"a","text":"hätte"},{"id":"b","text":"habe"},{"id":"c","text":"hatte"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"Для гипотетической ситуации используется Konjunktiv II: hätte.","en":"Use Konjunktiv II hätte for a hypothetical situation."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de'),
('DE-A2-14','grammar','A2','Ставить глагол в конец косвенного вопроса','{"ru":"Выбери правильный вариант на немецком языке.","en":"Choose the correct option in German."}'::jsonb,'{"type":"multiple_choice","prompt":"Kannst du mir sagen, wann der Zug ___?","options":[{"id":"a","text":"ankommt"},{"id":"b","text":"kommt an"},{"id":"c","text":"ankommen"}]}'::jsonb,'{"correct_option_id":"a"}'::jsonb,'{"ru":"В косвенном вопросе с wann глагол стоит в конце: wann der Zug ankommt.","en":"In an indirect wann-question, the verb goes to the end."}'::jsonb,3,ARRAY['german','a2'],ARRAY[]::text[],'{"enabled":true,"item_type":"grammar_rule"}'::jsonb,'Choose the correct German form.','de')
