INSERT INTO plan_templates
  (id,title,goal,level_min,level_max,duration_weeks,minutes_per_day,weekly_themes,status,language_code,version)
VALUES
  ('german-a1-a2-4-week','Deutsch A1-A2 · 4 Wochen','general','A1','A2',4,10,
   '[{"theme":"Begrüßung und Alltag","theme_ru":"Приветствия и повседневная жизнь","theme_en":"Greetings and everyday life","objective":"Научиться здороваться, представляться, говорить о семье, времени и простых ежедневных действиях.","objective_en":"Learn to greet people, introduce yourself and talk about family, time and simple daily routines.","tasks":["DE-A1-01","DE-A1-02","DE-A1-03","DE-A1-04","DE-A1-05","DE-A1-06","DE-A1-07"]},{"theme":"Menschen, Orte und Pläne","theme_ru":"Люди, места и планы","theme_en":"People, places and plans","objective":"Закрепить артикли, отрицание, отделяемые глаголы и простые ситуации в городе.","objective_en":"Practise articles, negation, separable verbs and simple situations around town.","tasks":["DE-A1-08","DE-A1-09","DE-A1-10","DE-A1-11","DE-A1-12","DE-A1-13","DE-A1-14"]},{"theme":"Erlebnisse und Alltag","theme_ru":"События и повседневное общение","theme_en":"Experiences and everyday communication","objective":"Освоить основные конструкции Perfekt, сравнения, советы и описание опыта.","objective_en":"Practise basic Perfekt forms, comparisons, advice and describing experiences.","tasks":["DE-A2-01","DE-A2-02","DE-A2-03","DE-A2-04","DE-A2-05","DE-A2-06","DE-A2-07"]},{"theme":"Gespräche und Zusammenhänge","theme_ru":"Разговоры и связные высказывания","theme_en":"Conversations and connected ideas","objective":"Научиться строить придаточные предложения, вежливые просьбы и простые гипотезы.","objective_en":"Build subordinate clauses, polite requests and simple hypothetical statements.","tasks":["DE-A2-08","DE-A2-09","DE-A2-10","DE-A2-11","DE-A2-12","DE-A2-13","DE-A2-14"]}]'::jsonb,'published','de',1)
